  3	{% block seo %}
  4	<meta property="og:title" content="{{content.title}}">
  5	{% if content.description %}
  6	<meta property="og:description" content="{{ content.description | replace(from='"', to="") | truncate(length=100, end="...") }}">
  7	{% else %}
  8	<meta property="og:description" content="{{ content.html | striptags | trim_start_matches(pat=content.title) | truncate(length=100, end="...") }}">
  9	{%- endif %}
 10	{% if content.card_image %}
 11	<meta property="og:image" content="{{url_for(path=content.card_image, abs=true)}}">
 12	{% elif site.card_image %}
 13	<meta property="og:image" content="{{url_for(path=site.card_image, abs=true)}}">
 14	{% endif %}
 15	{% if site.url %}
 16	<meta property="og:url" content="{{url_for(path=content.slug, abs=true)}}.html">
 17	{% endif %}
 18	<meta property="og:type" content="article">
 19	<meta property="og:site_name" content="{{site.name}}">
 20	{% if content.date %}
 21	<meta property="article:published_time" content="{{content.date | date(format=' %+')}}">
 22	{% endif %}
 23	{% if site.url and content.authors %}
 24	<meta property="article:author" content="{{url_for(path='author-' ~ content.authors.0 ~ '.html', abs=true)}}">
 25	{% endif %}
 26	
 27	{% include "json_ld_content.html" ignore missing%}
 28	{% endblock %}
 29	
 30	{% block head %}
 31	{{ super() }}
 32	<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.10.0/styles/github.min.css" id="highlightjs-theme" />
 33	{%if content.extra.math %}
 34	<script type="text/x-mathjax-config">
 35	  MathJax.Hub.Config({tex2jax: {inlineMath: [['$','$'], ['\\(','\\)']]}});
 36	</script>
 37	<script type="text/javascript" src="https://cdn.mathjax.org/mathjax/latest/MathJax.js?config=TeX-AMS-MML_HTMLorMML">
 38	</script>
 39	{% endif %}
 40	
 41	{% endblock %}
 42	
 43	
 44	{% block main %}
 45	
 46	{% if content.banner_image %}
 47	<div class="content-banner-image" style="background-image: url({{content.banner_image}});"></div>
 48	{% endif %}
 49	
 50	<article class="h-entry">
 51	  <data class="p-name" value="{{ content.title }}"></data>
 52	  <a class="u-url" href="{{url_for(path=content.slug ~ '.html')}}" style="display: none;"></a>
 53	  {% if content.date %}
 54	  <time class="dt-published" datetime="{{ content.date | date(format='%+') }}" style="display: none;">{{ content.date | default_date_format }}</time>
 55	  {% endif %}
 56	
 57	  {% if content.stream == "draft" %}
 58	  <div class="draft-warning" style="background-color: #fff3cd; border: 1px solid #ffeaa7; border-radius: 4px; padding: 12px; margin-bottom: 20px; color: #856404;">
 59	    <strong>⚠️ Draft Post:</strong> This post is a draft and may not be complete yet.
 60	  </div>
 61	  {% endif %}
 62	
 63	  {% include "content_title.html" ignore missing %}
 64	  {% if content.series %}
 65	  <div class="content-series">
 66	    <p><small>Published as part of '<a href="{{ url_for(path='series-' ~ content.series ~ '.html') }}">{{ series_display_name(series=content.series) }}</a>' series.</small></p>
 67	  </div>
 68	  {% endif %}
 69	  {% if content.toc %}
 70	  <div class="content-toc">
 71	    <a href="#" id="toc"></a>
 72	    <details>
 73	    <summary>🗒️</summary>
 74	    {{ content.toc }}
 75	    </details>
 76	  </div>
 77	  {% endif %}
 78	
 79	  <div class="content-html e-content">{{ content.html }}</div>
 80	  {% if content.date %}
 81	  <footer class="data-tags-footer">
 82	
 83	    <div class="content-authors-flex">
 84	      <div class="content-authors-full">
 85	        {% include "content_authors.html" ignore missing %}
 86	      </div>
 87	
 88	      <div class="date-tags-container">
 89	        <div class="content-date">
 90	          {% include "content_date.html" ignore missing %}
 91	          {% if content.stream and content.stream != "index" %}
 92	          <div class="content-stream">
 93	            {% set slug = content.stream | trim | slugify %}
 94	            {% set link = slug ~ ".html"%}
 95	            <small><a href="{{url_for(path=link)}}">{{ stream_display_name(stream=content.stream) }}</a></small>
 96	          </div>
 97	          {% endif %}
 98	        </div>
 99	
100	        <ul class="content-tags">
101	          {% for tag in content.tags %}
102	          {% set slug = "tag-" ~ tag | trim | slugify %}
103	          {% set link = slug ~ ".html"%}
104	          <li><a href="{{url_for(path=link)}}" class="p-category">{{ tag }}</a></li>
105	          {% endfor %}
106	        </ul>
107	      </div>
108	    </div>
109	  </footer>
110	  {% endif %}
111	</article>
112	
113	{% if site.enable_related_content and not content.series %}
114	{% if content.back_links %}
115	<article>
116	  Back-links
117	  <ul>
118	    {% for item in content.back_links | slice(end=10) %}
119	    <li><a href="{{url_for(path=item.slug ~ '.html')}}">{{item.title}}</a></li>
120	    {% endfor %}
121	  </ul>
122	</article>
123	{% endif %}
124	
125	{% if content.tags %}
126	  {# Only the first tag for now #}
127	  {% set tag = content.tags[0] %}
128	  {% set tag_slug = tag | slugify %}
129	  {% set related_content = site_data.tag.map[tag_slug] %}
130	  {% if related_content | length > 1 %}
131	  <article>
132	    Related {{tag}} content
133	    <ul>
134	      {% for item in related_content | sort(attribute="date") | reverse | slice(end=5) %}
135	      {% if item.slug == content.slug or item in content.back_links %}
136	      {% continue %}
137	      {% endif %}
138	      <li><a href="{{url_for(path=item.slug ~ '.html')}}">{{item.title}}</a></li>
139	      {% endfor %}
140	    </ul>
141	  </article>
142	  {% endif %}
143	{% endif %}
144	{% endif %}
145	
146	{% if site.show_next_prev_links and (content.previous or content.next) %}
147	<article>
148	  <nav style="display: flex; justify-content: space-between;">
149	    <div>
150	      {% if content.previous %}<a href="{{url_for(path=content.previous.slug ~ '.html')}}">← {{ content.previous.title }}</a>{% endif %}
151	    </div>
152	    <div>
153	      {% if content.next %}<a href="{{url_for(path=content.next.slug ~ '.html')}}">{{ content.next.title }} →</a>{% endif %}
154	    </div>
155	  </nav>
156	</article>
157	{% endif %}
158	
159	{% if comments is defined %}
160	    <article>{{ comments }}</article>
161	{% elif site.extra.comments.source is defined and content.date %}
162	    {%include "comments.html" ignore missing %}
163	{% endif %}
164	
165	{% if content.source_path is string and (site.publish_md or site.source_repository) %}
166	<article>
167	<div class="content-source">
168	  {% set source_url = source_link(content=content) %}
169	  {% if source_url %}
170	    <a href="{{url_for(path=source_url)}}" rel="nofollow">📄 View source</a>
171	  {% endif %}
172	</div>
173	</article>
174	{% endif %}
175	
176	
177	{% endblock %}
178	
179	{% block tail %}
180	{{ super() }}
181	<script src="https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.10.0/highlight.min.js"></script>
182	<script>
183	  hljs.highlightAll();
184	</script>
185	
186	{%if content.extra.mermaid %}
187	<script src="https://cdnjs.cloudflare.com/ajax/libs/mermaid/11.3.0/mermaid.min.js"></script>
188	<script>
189	  var config = {
190	    startOnLoad: true,
191	    theme: '{{content.extra.mermaid_theme | default(value="default") }}',
192	    flowchart: { useMaxWidth: false, htmlLabels: true }
193	  };
194	  mermaid.initialize(config);
195	  window.mermaid.init(undefined, document.querySelectorAll('.language-mermaid'));
196	</script>
197	{% endif %}
198	{% endblock %}

